   1  using UnityEngine;
   2  using UnityEngine.InputSystem;
   3  using UnityEngine.UI;
   4  
   5  // Runs before gameplay input so opening inspection cannot also move the player.
   6  [DefaultExecutionOrder(-100)]
   7  [RequireComponent(typeof(InventorySystem))]
   8  public class InventoryInspection : MonoBehaviour
   9  {
  10      public static bool IsOpen { get; private set; }
  11  
  12      private const float HoldDuration = 0.35f;
  13      private const float RotationSpeed = 90f;
  14      private static readonly Key[] SlotKeys = { Key.Digit1, Key.Digit2, Key.Digit3, Key.Digit4, Key.Digit5 };
  15  
  16      private InventorySystem inventory;
  17      private int heldSlot = -1;
  18      private int inspectedSlot = -1;
  19      private float holdStartedAt;
  20      private bool waitForRelease;
  21      private Vector2 rotation;
  22      private Canvas canvas;
  23      private Image itemImage;
  24      private Text title;
  25  
  26      private void Awake()
  27      {
  28          inventory = GetComponent<InventorySystem>();
  29      }
  30  
  31      private void OnDisable()
  32      {
  33          Close();
  34          heldSlot = -1;
  35      }
  36  
  37      private void Update()
  38      {
  39          Keyboard keyboard = Keyboard.current;
  40          if (keyboard == null)
  41          {
  42              heldSlot = -1;
  43              return;
  44          }
  45  
  46          if (keyboard.escapeKey.wasPressedThisFrame)
  47          {
  48              Close();
  49              heldSlot = -1;
  50              // Esc must not immediately reopen an item whose slot key is still held.
  51              waitForRelease = true;
  52              return;
  53          }
  54  
  55          int slot = -1;
  56          for (int i = 0; i < Mathf.Min(SlotKeys.Length, inventory.SlotCount()); i++)
  57          {
  58              if (keyboard[SlotKeys[i]].isPressed)
  59              {
  60                  slot = i;
  61                  break;
  62              }
  63          }
  64  
  65          if (slot < 0)
  66          {
  67              heldSlot = -1;
  68              waitForRelease = false;
  69          }
  70          else if (!waitForRelease)
  71          {
  72              inventory.NotifyInteraction();
  73              if (slot != heldSlot)
  74              {
  75                  heldSlot = slot;
  76                  holdStartedAt = Time.unscaledTime;
  77              }
  78              if (Time.unscaledTime - holdStartedAt >= HoldDuration && inspectedSlot != slot)
  79              {
  80                  Open(slot);
  81              }
  82          }
  83  
  84          if (!IsOpen)
  85          {
  86              return;
  87          }
  88  
  89          Vector2 input = Vector2.zero;
  90          if (keyboard.wKey.isPressed) input.x -= 1f;
  91          if (keyboard.sKey.isPressed) input.x += 1f;
  92          if (keyboard.aKey.isPressed) input.y -= 1f;
  93          if (keyboard.dKey.isPressed) input.y += 1f;
  94          rotation += input * (RotationSpeed * Time.unscaledDeltaTime);
  95          rotation.x = Mathf.Repeat(rotation.x, 360f);
  96          rotation.y = Mathf.Repeat(rotation.y, 360f);
  97          // Rotate the flat sprite in 3D about its center, never translate it.
  98          itemImage.rectTransform.localRotation = Quaternion.Euler(rotation.x, rotation.y, 0f);
  99      }
 100  
 101      private void LateUpdate()
 102      {
 103          if (!IsOpen)
 104          {
 105              return;
 106          }
 107  
 108          Rect bounds = ((RectTransform)canvas.transform).rect;
 109          float aspect = itemImage.sprite.rect.width / itemImage.sprite.rect.height;
 110          float height = Mathf.Min(bounds.height * 0.76f, bounds.width * 0.84f / aspect);
 111          itemImage.rectTransform.sizeDelta = new Vector2(height * aspect, height);
 112      }
 113  
 114      private void Open(int slot)
 115      {
 116          Sprite sprite = inventory.GetSprite(slot);
 117          if (sprite == null)
 118          {
 119              return; // Empty slots and items without artwork have nothing to inspect.
 120          }
 121  
 122          if (canvas == null)
 123          {
 124              BuildView();
 125          }
 126          itemImage.sprite = sprite;
 127          itemImage.rectTransform.localRotation = Quaternion.identity;
 128          rotation = Vector2.zero;
 129          title.text = inventory.GetItem(slot);
 130          inspectedSlot = slot;
 131          IsOpen = true;
 132          canvas.gameObject.SetActive(true);
 133      }
 134  
 135      private void Close()
 136      {
 137          if (!IsOpen)
 138          {
 139              return;
 140          }
 141          IsOpen = false;
 142          inspectedSlot = -1;
 143          canvas.gameObject.SetActive(false);
 144          inventory.NotifyInteraction();
 145      }
 146  
 147      private void BuildView()
 148      {
 149          var root = new GameObject("Inventory inspection", typeof(RectTransform), typeof(Canvas), typeof(CanvasScaler));
 150          root.transform.SetParent(transform, false);
 151          canvas = root.GetComponent<Canvas>();
 152          canvas.renderMode = RenderMode.ScreenSpaceOverlay;
 153          canvas.sortingOrder = 100;
 154          var scaler = root.GetComponent<CanvasScaler>();
 155          scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;
 156          scaler.referenceResolution = new Vector2(1280f, 720f);
 157          scaler.screenMatchMode = CanvasScaler.ScreenMatchMode.Expand;
 158  
 159          var backdrop = new GameObject("Dim background", typeof(RectTransform), typeof(Image)).GetComponent<Image>();
 160          backdrop.transform.SetParent(root.transform, false);
 161          backdrop.color = new Color(0f, 0f, 0f, 0.78f);
 162          backdrop.raycastTarget = false;
 163          backdrop.rectTransform.anchorMin = Vector2.zero;
 164          backdrop.rectTransform.anchorMax = Vector2.one;
 165          backdrop.rectTransform.offsetMin = Vector2.zero;
 166          backdrop.rectTransform.offsetMax = Vector2.zero;
 167  
 168          itemImage = new GameObject("Inspected sprite", typeof(RectTransform), typeof(Image)).GetComponent<Image>();
 169          itemImage.transform.SetParent(root.transform, false);
 170          itemImage.raycastTarget = false;
 171          itemImage.preserveAspect = true;
 172          itemImage.rectTransform.anchorMin = itemImage.rectTransform.anchorMax = new Vector2(0.5f, 0.5f);
 173          itemImage.rectTransform.anchoredPosition3D = Vector3.zero;
 174  
 175          Font font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
 176          title = CreateLabel("Item name", font, 22, 0.94f);
 177          Text controls = CreateLabel("Controls", font, 14, 0.06f);
 178          controls.text = "W A S D  Rotate     /     ESC  Close";
 179          controls.color = new Color(1f, 1f, 1f, 0.7f);
 180      }
 181  
 182      private Text CreateLabel(string name, Font font, int size, float anchorY)
 183      {
 184          var label = new GameObject(name, typeof(RectTransform), typeof(Text)).GetComponent<Text>();
 185          label.transform.SetParent(canvas.transform, false);
 186          label.font = font;
 187          label.fontSize = size;
 188          label.alignment = TextAnchor.MiddleCenter;
 189          label.color = Color.white;
 190          label.raycastTarget = false;
 191          label.rectTransform.anchorMin = new Vector2(0.1f, anchorY);
 192          label.rectTransform.anchorMax = new Vector2(0.9f, anchorY);
 193          label.rectTransform.sizeDelta = new Vector2(0f, 36f);
 194          label.rectTransform.anchoredPosition = Vector2.zero;
 195          return label;
 196      }
 197  }
