   3  // Central inventory for the player: a fixed number of slots filled in pickup order.
   4  // Gameplay code adds items through TryAdd; UI code reads slots with GetItem.
   5  public class InventorySystem : MonoBehaviour
   6  {
   7      public static InventorySystem instance;
   8  
   9      // Includes rejected pickups so a full inventory is still revealed.
  10      public event System.Action Interacted;
  11  
  12      [SerializeField]
  13      private int slotCount = 5;
  14  
  15      private string[] items;
  16      private Sprite[] itemSprites;
  17      private int itemCount;
  18  
  19      private void Awake()
  20      {
  21          instance = this;
  22          items = new string[slotCount];
  23          itemSprites = new Sprite[slotCount];
  24          itemCount = 0;
  25      }
  26  
  27      public int SlotCount()
  28      {
  29          return slotCount;
  30      }
  31  
  32      public int ItemCount()
  33      {
  34          return itemCount;
  35      }
  36  
  37      public bool IsFull()
  38      {
  39          return itemCount >= slotCount;
  40      }
  41  
  42      public void NotifyInteraction()
  43      {
  44          Interacted?.Invoke();
  45      }
  46  
  47      // Stores the item in the next free slot. Returns false when the inventory is full.
  48      public bool TryAdd(string itemName, Sprite sprite = null)
  49      {
  50          if (IsFull())
  51          {
  52              Debug.Log("Inventory is full - could not pick up " + itemName);
  53              NotifyInteraction();
  54              return false;
  55          }
  56  
  57          items[itemCount] = itemName;
  58          itemSprites[itemCount] = sprite;
  59          itemCount += 1;
  60          Debug.Log("Picked up " + itemName + " (" + itemCount + "/" + slotCount + ")");
  61          NotifyInteraction();
  62          return true;
  63      }
  64  
  65      public Sprite GetSprite(int slot)
  66      {
  67          return slot >= 0 && slot < itemCount ? itemSprites[slot] : null;
  68      }
  69  
  70      // Returns the item name in the given slot, or an empty string for empty slots.
  71      public string GetItem(int slot)
  72      {
  73          if (slot < 0 || slot >= itemCount)
