 150      // Returns the unpicked item closest to the player that is within range.
 151      private static PickupItem NearestInRange()
 152      {
 153          PickupItem nearest = null;
 154          float nearestDistance = float.MaxValue;
 155  
 156          for (int i = 0; i < instanceCount; i++)
 157          {
 158              PickupItem candidate = instances[i];
 159              if (candidate == null || candidate.pickedUp || !candidate.isActiveAndEnabled)
 160              {
