 164              if (!candidate.IsInRange())
 165              {
 166                  continue;
 167              }
 168  
 169              float distance = candidate.DistanceSqr();
 170              if (distance < nearestDistance)
 171              {
 172                  nearestDistance = distance;
 173                  nearest = candidate;
 174              }
 175          }
 176  
 177          return nearest;
