   4  // A white, bottom-left inventory strip that disappears when it is not in use.
   5  [RequireComponent(typeof(InventorySystem), typeof(InventoryInspection))]
   6  public class InventoryHUD : MonoBehaviour
   7  {
   8      [SerializeField]
   9      private float slotWidth = 104f;
  10  
  11      [SerializeField]
  12      private float slotHeight = 52f;
  13  
  14      [SerializeField]
  15      private float gap = 6f;
  16  
  17      [SerializeField]
  18      private float margin = 24f;
  19  
  20      [SerializeField]
  21      private int fontSize = 13;
  22  
  23      private const float IdleDelay = 7f;
  24      private const float FadeDuration = 0.4f;
  25      private const float HeaderHeight = 26f;
  26      private InventorySystem inventory;
  27      private float lastInteractionTime;
  28      private float opacity;
  29      private GUIStyle captionStyle;
  30      private GUIStyle hintStyle;
  31      private GUIStyle itemStyle;
  32      private GUIStyle emptyStyle;
  33  
  34      private void Awake()
  35      {
  36          inventory = GetComponent<InventorySystem>();
  37      }
  38  
  39      private void OnEnable()
  40      {
  41          inventory.Interacted += Show;
  42          Show();
  43      }
  44  
  45      private void OnDisable()
  46      {
  47          inventory.Interacted -= Show;
  48      }
  49  
  50      private void Show()
  51      {
  52          lastInteractionTime = Time.unscaledTime;
  53          opacity = 1f;
  54      }
  55  
  56      private void Update()
  57      {
  58          if (Keyboard.current != null && Keyboard.current.iKey.isPressed)
  59          {
  60              Show();
  61          }
  62  
  63          Mouse mouse = Mouse.current;
  64          if (mouse != null)
  65          {
  66              Vector2 position = mouse.position.ReadValue();
  67              position = new Vector2(position.x, Screen.height - position.y) / UIScale();
  68              bool pointerActivity = mouse.delta.ReadValue().sqrMagnitude > 0f
  69                  || mouse.leftButton.wasPressedThisFrame || mouse.rightButton.wasPressedThisFrame
  70                  || mouse.scroll.ReadValue().sqrMagnitude > 0f;
  71              // A parked cursor should not prevent the inventory from fading.
  72              if (pointerActivity && PanelRect().Contains(position))
  73              {
  74                  Show();
  75              }
  76          }
  77  
  78          float fadeProgress = (Time.unscaledTime - lastInteractionTime - IdleDelay) / FadeDuration;
  79          opacity = 1f - Mathf.SmoothStep(0f, 1f, fadeProgress);
  80      }
  81  
  82      private static float UIScale()
  83      {
  84          return Mathf.Min(Screen.width / 1280f, Screen.height / 720f);
  85      }
  86  
  87      private Rect PanelRect()
  88      {
  89          float scale = UIScale();
  90          Rect safeArea = Screen.safeArea;
  91          float width = inventory.SlotCount() * slotWidth + (inventory.SlotCount() - 1) * gap;
  92          // IMGUI uses a top-left origin; Screen.safeArea uses a bottom-left origin.
  93          return new Rect(safeArea.xMin / scale + margin,
  94              (Screen.height - safeArea.yMin) / scale - margin - slotHeight - HeaderHeight,
  95              width, slotHeight + HeaderHeight);
  96      }
  97  
  98      private void OnGUI()
  99      {
 100          if (inventory == null || opacity <= 0f || InventoryInspection.IsOpen)
 101          {
 102              return;
 103          }
 104  
 105          BuildStyles();
 106          Color previousColor = GUI.color;
 107          Matrix4x4 previousMatrix = GUI.matrix;
 108          float scale = UIScale();
 109          GUI.matrix = Matrix4x4.Scale(new Vector3(scale, scale, 1f));
 110          GUI.color = new Color(1f, 1f, 1f, previousColor.a * opacity);
 111  
 112          Rect panel = PanelRect();
 113          string capacity = inventory.ItemCount() + " / " + inventory.SlotCount();
 114          if (inventory.IsFull())
 115          {
 116              capacity += "  FULL";
 117          }
 118          GUI.Label(new Rect(panel.x, panel.y, 96f, 18f), "INVENTORY", captionStyle);
 119          GUI.Label(new Rect(panel.x + 96f, panel.y, 100f, 18f), capacity, captionStyle);
 120          GUI.Label(new Rect(panel.xMax - 250f, panel.y, 250f, 18f), "HOLD 1\u20135  INSPECT     [I]  VIEW", hintStyle);
 121  
 122          for (int i = 0; i < inventory.SlotCount(); i++)
 123          {
 124              Rect cell = new Rect(panel.x + i * (slotWidth + gap), panel.y + HeaderHeight,
 125                  slotWidth, slotHeight);
 126              bool occupied = i < inventory.ItemCount();
 127              DrawRect(cell, new Color(0f, 0f, 0f, occupied ? 0.32f : 0.16f));
 128              Color border = new Color(1f, 1f, 1f, occupied ? 0.8f : 0.25f);
 129              DrawRect(new Rect(cell.x, cell.y, cell.width, 1f), border);
 130              DrawRect(new Rect(cell.x, cell.yMax - 1f, cell.width, 1f), border);
 131              DrawRect(new Rect(cell.x, cell.y, 1f, cell.height), border);
 132              DrawRect(new Rect(cell.xMax - 1f, cell.y, 1f, cell.height), border);
 133              GUI.Label(new Rect(cell.x + 10f, cell.y + 3f, 20f, 12f), (i + 1).ToString(), captionStyle);
 134              Rect label = new Rect(cell.x + 10f, cell.y + 18f, cell.width - 20f, cell.height - 22f);
 135              GUI.Label(label, occupied ? inventory.GetItem(i) : "\u2014", occupied ? itemStyle : emptyStyle);
 136          }
 137  
 138          GUI.color = previousColor;
 139          GUI.matrix = previousMatrix;
 140      }
 141  
 142      private static void DrawRect(Rect rect, Color color)
 143      {
 144          Color previousColor = GUI.color;
 145          GUI.color = previousColor * color;
 146          GUI.DrawTexture(rect, Texture2D.whiteTexture);
 147          GUI.color = previousColor;
 148      }
 149  
 150      private void BuildStyles()
 151      {
 152          if (itemStyle != null)
 153          {
 154              return;
 155          }
 156  
 157          // Start from plain styles rather than the editor-dependent GUI skin.
 158          itemStyle = new GUIStyle { fontSize = fontSize, alignment = TextAnchor.MiddleLeft, wordWrap = true };
 159          itemStyle.normal.textColor = Color.white;
 160          emptyStyle = new GUIStyle(itemStyle);
 161          emptyStyle.normal.textColor = new Color(1f, 1f, 1f, 0.3f);
 162          emptyStyle.alignment = TextAnchor.MiddleCenter;
 163          captionStyle = new GUIStyle(itemStyle) { fontSize = 11, fontStyle = FontStyle.Bold, wordWrap = false };
 164          captionStyle.normal.textColor = new Color(1f, 1f, 1f, 0.8f);
 165          hintStyle = new GUIStyle(captionStyle);
 166          hintStyle.normal.textColor = new Color(1f, 1f, 1f, 0.5f);
 167          hintStyle.alignment = TextAnchor.MiddleRight;
 168      }
 169  }
