   1  using UnityEngine;
   2  using UnityEngine.InputSystem;
   3  
   4  [RequireComponent(typeof(CharacterController))]
   5  public class PlayerController : MonoBehaviour
   6  {
   7      [SerializeField] private float moveSpeed = 5f;
   8      [SerializeField] private float jumpSpeed = 10f;
   9      [SerializeField] private float gravity = -9.81f;
  10  
  11      private CharacterController characterController;
  12      private float verticalVelocity;
  13  
  14      private void Awake()
  15      {
  16          characterController = GetComponent<CharacterController>();
  17      }
  18  
  19      private void Update()
  20      {
  21          if (InventoryInspection.IsOpen)
  22          {
  23              return;
  24          }
  25  
  26          if (Camera.main != null)
  27          {
  28              // Rotates the object to face the main camera continuously
  29              transform.LookAt(Camera.main.transform);
  30              transform.rotation = Quaternion.Euler(0, Camera.main.transform.eulerAngles.y, 0);
  31          }
  32          bool grounded = characterController.isGrounded;
  33          if (grounded && verticalVelocity < 0f)
  34          {
  35              verticalVelocity = -1f;
  36          }
  37  
  38          if (grounded && IsJumpPressed())
  39          {
  40              verticalVelocity = jumpSpeed;
  41          }
  42  
  43          verticalVelocity += gravity * Time.deltaTime;
  44  
  45          Vector2 input = GetMovementInput();
  46          Vector3 motion = (CameraRight() * input.x + CameraForward() * input.y) * moveSpeed;
  47          motion.y = verticalVelocity;
  48  
  49          characterController.Move(motion * Time.deltaTime);
  50      }
  51  
  52      // Space makes the player jump, but only when standing on the ground.
  53      private static bool IsJumpPressed()
  54      {
  55          Keyboard keyboard = Keyboard.current;
  56          return keyboard != null && keyboard.spaceKey.wasPressedThisFrame;
  57      }
  58  
  59      // W always moves the player away from the camera, A/S/D are relative to the
  60      // camera's facing, so movement follows where the camera is looking.
  61      private static Vector3 CameraForward()
  62      {
  63          if (Camera.main != null)
  64          {
  65              Vector3 forward = Camera.main.transform.forward;
  66              forward.y = 0f;
  67              if (forward.sqrMagnitude > 0.0001f)
  68              {
  69                  return forward.normalized;
  70              }
  71          }
  72  
  73          return Vector3.forward;
  74      }
  75  
  76      private static Vector3 CameraRight()
  77      {
  78          if (Camera.main != null)
  79          {
  80              Vector3 right = Camera.main.transform.right;
  81              right.y = 0f;
  82              if (right.sqrMagnitude > 0.0001f)
  83              {
  84                  return right.normalized;
  85              }
  86          }
  87  
  88          return Vector3.right;
  89      }
  90  
  91      private static Vector2 GetMovementInput()
  92      {
  93          Keyboard keyboard = Keyboard.current;
  94          if (keyboard == null)
  95          {
  96              return Vector2.zero;
  97          }
  98  
  99          Vector2 input = Vector2.zero;
 100          if (keyboard.wKey.isPressed) input.y += 1f;
 101          if (keyboard.sKey.isPressed) input.y -= 1f;
 102          if (keyboard.aKey.isPressed) input.x -= 1f;
 103          if (keyboard.dKey.isPressed) input.x += 1f;
 104          return input;
 105      }
 106  }
